registry = MLConfigRegistry()
base = {'batch_size': 8, 'precision': 'fp16', 'dropout': 0.1}
registry.register('embedder', 1, base)
base['batch_size'] = 999
registry.register('embedder', 2, {'batch_size': 16}, base_version=1)
assert registry.resolve('embedder', 1) == {'batch_size': 8, 'precision': 'fp16', 'dropout': 0.1}
assert registry.resolve('embedder', 2) == {'batch_size': 16, 'precision': 'fp16', 'dropout': 0.1}
view = registry.resolve('embedder', 2)
view['precision'] = 'tampered'
assert registry.resolve('embedder', 2)['precision'] == 'fp16'

registry = MLConfigRegistry()
registry.register('vision', 1, {'epochs': 3})
for call in (lambda: registry.register('vision', 1, {'epochs': 4}), lambda: registry.register('vision', 2, {'epochs': 4}, base_version=9), lambda: registry.register('vision', 2, {'nested': []}), lambda: registry.resolve('vision', 1, overrides={'missing': 3})):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
assert registry.resolve('vision', 1) == {'epochs': 3}
try:
    registry.resolve('vision')
    raise AssertionError('expected KeyError before activation')
except KeyError:
    pass

registry = MLConfigRegistry()
for call in (lambda: registry.register('', 1, {'x': 1}), lambda: registry.register('x', True, {'x': 1}), lambda: registry.register('x', 0, {'x': 1}), lambda: registry.register('x', 1, {'': 1}), lambda: registry.register('x', 1, {'x': float('inf')})):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
try:
    registry.versions('missing')
    raise AssertionError('expected KeyError')
except KeyError:
    pass
